import type { ArchetypeId, Slots } from './archetypes';

/**
 * Control-content library, version 0.2, approved by MK on 14 November 2026 (see index.ts): one entry per control.
 *
 * Coverage: every control that appears in the Essential findings or the Comprehensive blueprints of the four
 * fictional organisations (146 controls), as MK directed. Other controls fall back to the method's own wording and
 * are flagged as content not yet written (see index.ts). Each entry names its archetype and sources:
 *   L4      the target practice follows the bank's level 4 description
 *   EV      the record follows the evidence the bank names, restated as records management keeps
 *   MFRS:x  the pattern follows MK's existing MFRS question playbook x
 *   BANK    the target practice restates the bank's question as an operating practice (no level description exists)
 */
export type Entry = Slots & {
  id: string; a: ArchetypeId;
  /** The target operating practice, in full. */
  target: string;
  /** A version of the target of at most 150 characters, for labels with a hard limit; where absent the target fits. */
  brief?: string;
  /** Responsible function, where the method's first-named owner is not the right one. */
  fn?: string;
  /** Where the archetype's activities or measure do not fit, the entry's own. */
  activities?: string[]; measure?: string; onFailure?: string;
  src: string[];
};

